@props(['name' => 'body', 'value' => '', 'label' => 'Message', 'rows' => 10, 'required' => true])
<div class="email-composer" data-email-composer>
    <label>{{ $label }}<textarea name="{{ $name }}" rows="{{ $rows }}" @required($required) data-email-source>{{ $value }}</textarea></label>
    <div class="email-format-toolbar" role="toolbar" aria-label="Message formatting">
        <button type="button" class="button secondary" data-format="bold" title="Bold"><strong>B</strong></button>
        <button type="button" class="button secondary" data-format="italic" title="Italic"><em>I</em></button>
        <button type="button" class="button secondary" data-format="heading" title="Heading">H</button>
        <button type="button" class="button secondary" data-format="list" title="Bulleted list">• List</button>
        <button type="button" class="button secondary" data-format="link" title="Link">Link</button>
        <button type="button" class="button secondary" data-format="quote" title="Callout">Callout</button>
        <button type="button" class="button secondary" data-preview-toggle aria-pressed="false">Preview</button>
    </div>
    <div class="email-composer-preview" data-email-preview hidden></div>
</div>
