@push('styles')<style>.email-format-toolbar{display:flex;flex-wrap:wrap;gap:6px;margin:-7px 0 10px}.email-format-toolbar .button{min-height:34px;padding:5px 10px}.email-composer-preview{min-height:170px;margin:8px 0 16px;border:1px solid var(--line);border-radius:7px;background:#fff;padding:20px;line-height:1.65}.email-composer-preview h2{font-size:22px;margin:20px 0 8px}.email-composer-preview blockquote{margin:16px 0;border-left:4px solid var(--brand);background:var(--soft);padding:10px 14px}.email-composer-preview ul{padding-left:24px}</style>@endpush
@push('scripts')<script nonce="{{ request()->attributes->get('csp_nonce') }}">(() => { const escape = value => value.replace(/[&<>"']/g, char => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[char])); const render = source => { let html = escape(source); html = html.replace(/^## (.+)$/gm,'<h2>$1</h2>').replace(/^# (.+)$/gm,'<h2>$1</h2>').replace(/^&gt; (.+)$/gm,'<blockquote>$1</blockquote>').replace(/^[-*] (.+)$/gm,'<li>$1</li>').replace(/(<li>.*<\/li>\n?)+/g,'<ul>$&</ul>').replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>').replace(/\*(.+?)\*/g,'<em>$1</em>').replace(/\[([^\]]+)\]\((https?:\/\/[^\s)]+)\)/g,'<a href="$2">$1</a>').replace(/\n{2,}/g,'</p><p>').replace(/\n/g,'<br>'); return '<p>'+html+'</p>'; }; document.querySelectorAll('[data-email-composer]').forEach(composer => { if(composer.dataset.ready) return; composer.dataset.ready='1'; const input=composer.querySelector('[data-email-source]'); const preview=composer.querySelector('[data-email-preview]'); const wrap=(before,after=before,placeholder='text')=>{const start=input.selectionStart,end=input.selectionEnd,selected=input.value.slice(start,end)||placeholder;input.setRangeText(before+selected+after,start,end,'end');input.focus();}; composer.querySelectorAll('[data-format]').forEach(button=>button.addEventListener('click',()=>{const action=button.dataset.format;if(action==='bold')wrap('**','**');if(action==='italic')wrap('*','*');if(action==='heading')wrap('## ','','Heading');if(action==='list')wrap('- ','','List item');if(action==='quote')wrap('> ','','Important information');if(action==='link')wrap('[','](https://)','Link text');})); composer.querySelector('[data-preview-toggle]').addEventListener('click',event=>{const showing=!preview.hidden;preview.hidden=showing;event.currentTarget.setAttribute('aria-pressed',String(!showing));event.currentTarget.textContent=showing?'Preview':'Edit';if(!showing)preview.innerHTML=render(input.value);}); }); })();</script>@endpush
@endonce
